def solve():
    n = int(input())
    a = list(map(int, input().split()))
    for i in range(n):
        a[i] = 2 ** log2(i + 1) + a[i] if i + 1 <= n else 2 ** log2(i) + a[i]
    a.sort()
    a.sort(key=lambda x: 2 ** log2(ceil(log2(x))), reverse=True)
    for i in range(n):
        a[i] = a[i] - 2 ** log2(i + 1)
    return all(a[i] <= a[i + 1] for i in range(n - 1))

