import math

def solve():
    x, y, n = map(int, input().split())
    if n == 3 and x == y - 1:
        return [x, y - 1, y]
    elif (y - x) % (n - 2) > 0 or (y - x) < n - 2:
        return [-1]
    inc = [x]
    while len(inc) < n:
        inc.append(inc[-1] + math.ceil((y - inc[-1]) / (n - len(inc))))
    if inc[-1]!= y:
        return [-1]
    return inc
