import sys
from collections import deque
from math import ceil

def solve():
    n, m = map(int, input().split())
    x1, y1, x2, y2 = map(int, input().split())
    x1 -= 1
    y1 -= 1
    x2 -= 1
    y2 -= 1

    dx = [-1, 1, 0, 0]
    dy = [0, 0, -1, 1]

    def is_in_board(r, c):
        return 0 <= r < n and 0 <= c < m

    def bfs(sx, sy, ex, ey):
        q = deque([(sx, sy)])
        dist = {(sx, sy): 0}
        for _ in range(n * m):
            x, y = q.popleft()
            if (x, y) == (ex, ey):
                return True
            for d in range(4):
                nx, ny = x + dx[d], y + dy[d]
                if is_in_board(nx, ny) and (nx, ny) not in dist:
                    q.append((nx, ny))
                    dist[(nx, ny)] = dist[(x, y)] + 1
        return False

    ans = min(min(min(n - 1, m - 1) - 1, min(x1, x2)), min(min(n - 1, m - 1) - 1, min(y1, y2)))
    if bfs(0, 0, x1, y1) and bfs(x2, y2, n - 1, m - 1):
        ans += 1
    if bfs(0, m - 1, x1, y1) and bfs(x2, y2, n - 1, 0):
        ans += 1
    if bfs(n - 1, 0, x1, y1) and bfs(x2, y2, 0, m - 1):
        ans += 1
    if bfs(n - 1, m - 1, x1, y1) and bfs(x2, y2, 0, 0):
        ans += 1
    return ans

