from typing import Tuple

def solve() -> None:
    t = int(stdin.readline().strip())
    for _ in range(t):
        _ = stdin.readline().strip()
        p1 = tuple(map(int, stdin.readline().split()))
        p2 = tuple(map(int, stdin.readline().split()))
        p3 = tuple(map(int, stdin.readline().split()))

        mp = {
            'horizontal': False,
           'vertical': False
        }

        x_set = {p1[0], p2[0], p3[0]}
        y_set = {p1[1], p2[1], p3[1]}

        if len(x_set) == 1 or len(y_set) == 1:
            print('YES')
            continue

        x_mn, x_mx = min(x_set), max(x_set)
        y_mn, y_mx = min(y_set), max(y_set)

        x_md = (x_mn + x_mx) // 2
        y_md = (y_mn + y_mx) // 2

        def get_sign(p: Tuple[int, int]) -> str:
            return 1 if p[0] > x_md else (-1 if p[0] < x_md else 0)

        def is_intersect(p1: Tuple[int, int], p2: Tuple[int, int], p3: Tuple[int, int]) -> bool:
            a = p2[1] - p1[1]
            b = p1[0] - p2[0]
            c = (p2[0] * p1[1] - p1[0] * p2[1])

            d = p3[1] - p1[1]
            e = p1[0] - p3[0]
            f = (p3[0] * p1[1] - p1[0] * p3[1])

            t = (a * e - b * d)
            if t == 0:
                return False
            t = (c * e - f) / t
            u = (a * f - c * d) / t
            return (0 <= t <= 1) and (0 <= u <= 1)

        if get_sign(p1) == get_sign(p2) == get_sign(p3)!= 0:
            mp['horizontal'] = True
        if get_sign(p1)!= get_sign(p2) and get_sign(p1)!= get_sign(p3) and is_intersect(p1, p2, p3):
            mp['vertical'] = True

        print('YES' if any(mp.values()) else 'NO')

