        for i in range(n):
            total = 0
            for j in range(change[i].__len__()):
                total += change[i][j]
            if total % 2!= 0:
                change[i][-1] *= -1
        queue = deque()
        for i in range(n):
            total = 0
            for j in range(change[i].__len__() - 1, -1, -1):
                total += change[i][j]
                queue.appendleft(arr[i] + total)
        print(*queue)

